#include <exception>
#include <iostream>

void riskyFunction() noexcept {  // noexcept ensures no exceptions can escape; compiler may optimize aggressively, assuming no unwinding.
    throw std::runtime_error("This will trigger std::terminate()");  // At compile-time, the compiler flags this as a potential issue but enforces at runtime.
}

int main() {
    try {
        riskyFunction();  // Runtime: Compiler-generated code calls the exception throwing mechanism; when noexcept is violated, std::terminate() is invoked without entering the catch block.
    } catch (const std::exception& e) {
        std::cout << "Caught: " << e.what() << std::endl;  // This won't execute due to std::terminate().
    }
    return 0;
}
